<script>
(function(){var key='slate-growth-lab-progress-v1', saved={};try{saved=JSON.parse(localStorage.getItem(key)||'{}')}catch(e){}var rows=document.querySelectorAll('#gl-tracker .gl-progress-row');function render(){var done=0;rows.forEach(function(row){var box=row.querySelector('input'), bar=row.querySelector('.gl-bar i'), pct=row.querySelector('.gl-task-pct');if(saved[box.dataset.task]){box.checked=true;done++}bar.style.width=box.checked?'100%':'0%';pct.textContent=box.checked?'Complete':'Next'});var total=document.querySelector('#gl-tracker');if(total) total.setAttribute('data-complete',done+'/'+rows.length)}rows.forEach(function(row){row.querySelector('input').addEventListener('change',function(){saved[this.dataset.task]=this.checked;localStorage.setItem(key,JSON.stringify(saved));render()})});render()})();
